#!/bin/bash
set -euo pipefail
reader_test_root="$(cd "$(dirname "$0")/.." && pwd)"
reader_test_build="$reader_test_root/build/tests"
mkdir -p "$reader_test_build/ModuleCache"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/TextFile.swift" "$reader_test_root/Tests/FileCoreTests.swift" -o "$reader_test_build/FileCoreTests"
"$reader_test_build/FileCoreTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/TextFeatures.swift" "$reader_test_root/Sources/MarkdownLinks.swift" "$reader_test_root/Tests/TextFeatureTests.swift" -o "$reader_test_build/TextFeatureTests"
"$reader_test_build/TextFeatureTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/TextFeatures.swift" "$reader_test_root/Sources/MarkdownLinks.swift" "$reader_test_root/Sources/ReadingDocument.swift" "$reader_test_root/Tests/ReadingDocumentTests.swift" -o "$reader_test_build/ReadingDocumentTests"
"$reader_test_build/ReadingDocumentTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/TextFeatures.swift" "$reader_test_root/Sources/MarkdownLinks.swift" "$reader_test_root/Sources/TextEditing.swift" "$reader_test_root/Sources/Appearance.swift" "$reader_test_root/Tests/LineIndexTests.swift" -o "$reader_test_build/LineIndexTests"
"$reader_test_build/LineIndexTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/TextSearch.swift" "$reader_test_root/Tests/TextSearchTests.swift" -o "$reader_test_build/TextSearchTests"
"$reader_test_build/TextSearchTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/TextAnchorMapper.swift" "$reader_test_root/Tests/TextAnchorMapperTests.swift" -o "$reader_test_build/TextAnchorMapperTests"
"$reader_test_build/TextAnchorMapperTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/TextAnchorMapper.swift" "$reader_test_root/Sources/BookmarkStore.swift" "$reader_test_root/Tests/BookmarkStoreTests.swift" -o "$reader_test_build/BookmarkStoreTests"
"$reader_test_build/BookmarkStoreTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/AnnotationStore.swift" "$reader_test_root/Sources/ReadingBriefExporter.swift" "$reader_test_root/Tests/AnnotationStoreTests.swift" -o "$reader_test_build/AnnotationStoreTests"
"$reader_test_build/AnnotationStoreTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/WorkspaceScanner.swift" "$reader_test_root/Sources/GlobalSearchEngine.swift" "$reader_test_root/Sources/ReadingListStore.swift" "$reader_test_root/Sources/TextSearch.swift" "$reader_test_root/Sources/TextFile.swift" "$reader_test_root/Tests/WorkspaceParityTests.swift" -o "$reader_test_build/WorkspaceParityTests"
"$reader_test_build/WorkspaceParityTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/MarkdownLinks.swift" "$reader_test_root/Tests/MarkdownLinksTests.swift" -o "$reader_test_build/MarkdownLinksTests"
"$reader_test_build/MarkdownLinksTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/TextFeatures.swift" "$reader_test_root/Sources/MarkdownLinks.swift" "$reader_test_root/Sources/ReadingDocument.swift" "$reader_test_root/Tests/MarkdownLinkRenderingTests.swift" -o "$reader_test_build/MarkdownLinkRenderingTests"
"$reader_test_build/MarkdownLinkRenderingTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/UpdateService.swift" "$reader_test_root/Tests/UpdateServiceTests.swift" -o "$reader_test_build/UpdateServiceTests"
"$reader_test_build/UpdateServiceTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/MarkdownTableEditing.swift" "$reader_test_root/Tests/MarkdownTableEditingTests.swift" "$reader_test_root/Sources/TextEditing.swift" -o "$reader_test_build/MarkdownTableEditingTests"
"$reader_test_build/MarkdownTableEditingTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/MarkdownAssetWriter.swift" "$reader_test_root/Tests/MarkdownAssetWriterTests.swift" -framework AppKit -o "$reader_test_build/MarkdownAssetWriterTests"
"$reader_test_build/MarkdownAssetWriterTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/ReadingMediaCache.swift" "$reader_test_root/Tests/ReadingMediaCacheTests.swift" -framework AppKit -o "$reader_test_build/ReadingMediaCacheTests"
"$reader_test_build/ReadingMediaCacheTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/MarkdownListEditing.swift" "$reader_test_root/Sources/TextEditing.swift" "$reader_test_root/Tests/MarkdownListEditingTests.swift" -o "$reader_test_build/MarkdownListEditingTests"
"$reader_test_build/MarkdownListEditingTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/MermaidFlowchart.swift" "$reader_test_root/Tests/MermaidFlowchartTests.swift" -framework AppKit -o "$reader_test_build/MermaidFlowchartTests"
"$reader_test_build/MermaidFlowchartTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/TextEditing.swift" "$reader_test_root/Tests/TextEditingTests.swift" -o "$reader_test_build/TextEditingTests"
"$reader_test_build/TextEditingTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/TextFile.swift" "$reader_test_root/Sources/WorkspaceStore.swift" "$reader_test_root/Tests/WorkspaceStoreTests.swift" -o "$reader_test_build/WorkspaceStoreTests"
"$reader_test_build/WorkspaceStoreTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/QuickOpenController.swift" "$reader_test_root/Tests/QuickOpenTests.swift" -o "$reader_test_build/QuickOpenTests"
"$reader_test_build/QuickOpenTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/MermaidSequence.swift" "$reader_test_root/Tests/MermaidSequenceTests.swift" -o "$reader_test_build/MermaidSequenceTests"
"$reader_test_build/MermaidSequenceTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/TextFeatures.swift" "$reader_test_root/Sources/MarkdownLinks.swift" "$reader_test_root/Sources/TextFormatting.swift" "$reader_test_root/Sources/LineChanges.swift" "$reader_test_root/Sources/JSONStructureController.swift" "$reader_test_root/Tests/FormattingParityTests.swift" -o "$reader_test_build/FormattingParityTests"
"$reader_test_build/FormattingParityTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/TextFeatures.swift" "$reader_test_root/Sources/MarkdownLinks.swift" "$reader_test_root/Sources/ReadingDocument.swift" "$reader_test_root/Sources/ReadingMedia.swift" "$reader_test_root/Sources/ReadingShare.swift" "$reader_test_root/Tests/RichReadingTests.swift" -o "$reader_test_build/RichReadingTests"
"$reader_test_build/RichReadingTests"
reader_ui_sources=()
for reader_source in "$reader_test_root"/Sources/*.swift; do
    if [ "$(basename "$reader_source")" != "main.swift" ]; then reader_ui_sources+=("$reader_source"); fi
done
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "${reader_ui_sources[@]}" "$reader_test_root/Tests/UIWorkflowTests.swift" -o "$reader_test_build/UIWorkflowTests"
"$reader_test_build/UIWorkflowTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "$reader_test_root/Sources/WindowMenuBar.swift" "$reader_test_root/Tests/WindowMenuBarTests.swift" -o "$reader_test_build/WindowMenuBarTests"
"$reader_test_build/WindowMenuBarTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "${reader_ui_sources[@]}" "$reader_test_root/Tests/ReaderMenusTests.swift" -o "$reader_test_build/ReaderMenusTests"
"$reader_test_build/ReaderMenusTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "${reader_ui_sources[@]}" "$reader_test_root/Tests/MacParityWorkflowTests.swift" -o "$reader_test_build/MacParityWorkflowTests"
"$reader_test_build/MacParityWorkflowTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "${reader_ui_sources[@]}" "$reader_test_root/Tests/AppearanceParityTests.swift" -o "$reader_test_build/AppearanceParityTests"
"$reader_test_build/AppearanceParityTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "${reader_ui_sources[@]}" "$reader_test_root/Tests/LayoutParityTests.swift" -o "$reader_test_build/LayoutParityTests"
"$reader_test_build/LayoutParityTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "${reader_ui_sources[@]}" "$reader_test_root/Tests/CurrentSyncWorkflowTests.swift" -o "$reader_test_build/CurrentSyncWorkflowTests"
"$reader_test_build/CurrentSyncWorkflowTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "${reader_ui_sources[@]}" "$reader_test_root/Tests/WorkspaceWindowTests.swift" -o "$reader_test_build/WorkspaceWindowTests"
"$reader_test_build/WorkspaceWindowTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "${reader_ui_sources[@]}" "$reader_test_root/Tests/ReadingListWindowTests.swift" -o "$reader_test_build/ReadingListWindowTests"
"$reader_test_build/ReadingListWindowTests"
xcrun swiftc -module-cache-path "$reader_test_build/ModuleCache" "${reader_ui_sources[@]}" "$reader_test_root/Tests/AnnotationPanelWindowTests.swift" -o "$reader_test_build/AnnotationPanelWindowTests"
"$reader_test_build/AnnotationPanelWindowTests"
